import math

def run_ames_rmsle_pipeline(train_rows: list[dict], test_rows: list[dict], n_splits: int = 3) -> dict:
    # Invariant 1: Log1p Target
    train_log_prices = [math.log1p(row['SalePrice']) for row in train_rows]
    global_log_mean = sum(train_log_prices) / len(train_log_prices) if train_log_prices else 0.0

    # Invariant 2: Strict Out-of-Fold Encoding
    oof_neighborhood_encoding = [0.0] * len(train_rows)
    for i in range(len(train_rows)):
        fold_k = i % n_splits
        neighborhood = train_rows[i]['Neighborhood']

        # Collect log prices for rows NOT in fold k with the same neighborhood
        oof_values = [
            train_log_prices[j] 
            for j in range(len(train_rows)) 
            if (j % n_splits != fold_k) and (train_rows[j]['Neighborhood'] == neighborhood)
        ]

        if oof_values:
            oof_neighborhood_encoding[i] = sum(oof_values) / len(oof_values)
        else:
            oof_neighborhood_encoding[i] = global_log_mean

    # Calculate global means for the prediction formula
    # TotalSF = sum(max(0.0, float(row.get(c) or 0.0)) for c in ('TotalBsmtSF','FirstFlrSF','SecondFlrSF'))
    def get_total_sf(row):
        return sum(max(0.0, float(row.get(c) or 0.0)) for c in ('TotalBsmtSF', 'FirstFlrSF', 'SecondFlrSF'))

    train_sfs = [get_total_sf(row) for row in train_rows]
    train_quals = [float(row['OverallQual']) for row in train_rows]

    mean_sf = sum(train_sfs) / len(train_sfs) if train_sfs else 0.0
    mean_qual = sum(train_quals) / len(train_quals) if train_quals else 0.0

    # Neighborhood mapping for test set (using all train data)
    nb_map = {}
    nb_counts = {}
    for row, lp in zip(train_rows, train_log_prices):
        nb = row['Neighborhood']
        nb_map[nb] = nb_map.get(nb, 0.0) + lp
        nb_counts[nb] = nb_counts.get(nb, 0) + 1

    nb_means = {nb: nb_map[nb] / nb_counts[nb] for nb in nb_map}

    # Invariant 3: TotalSF & Prediction
    test_total_sf = []
    predictions = []

    for row in test_rows:
        tsf = get_total_sf(row)
        test_total_sf.append(tsf)

        nb = row['Neighborhood']
        nb_val = nb_means.get(nb, global_log_mean)
        qual = float(row['OverallQual'])

        # Formula: Neighborhood log-mean + 0.02*(OverallQual - mean_qual) + 0.00003*(TotalSF - mean_sf)
        log_pred = nb_val + 0.02 * (qual - mean_qual) + 0.00003 * (tsf - mean_sf)
        predictions.append(math.expm1(log_pred))

    return {
        'oof_neighborhood_encoding': oof_neighborhood_encoding,
        'test_total_sf': test_total_sf,
        'predictions': predictions
    }

import time
from collections import OrderedDict
from typing import Any, Callable, List, Tuple, Optional

class TLRUCache:
    def __init__(
        self, 
        maxsize: int, 
        ttu: Callable[[Any, Any, float], float], 
        timer: Callable[[], float] = time.monotonic
    ):
        self.maxsize = maxsize
        self._ttu = ttu
        self._timer = timer
        self._data = OrderedDict()  # Stores (value, expiry)

    def expire(self, time_now: Optional[float] = None) -> List[Tuple[Any, Any]]:
        if time_now is None:
            time_now = self._timer()

        expired = []
        # Invariant 2: Check ALL items because TTU can be out-of-order
        keys_to_remove = [
            k for k, (v, exp) in self._data.items() if exp <= time_now
        ]
        for k in keys_to_remove:
            val, _ = self._data.pop(k)
            expired.append((k, val))
        return expired

    def __getitem__(self, key: Any) -> Any:
        self.expire()
        if key not in self._data:
            raise KeyError(key)
        val, exp = self._data[key]
        self._data.move_to_end(key)
        return val

    def __setitem__(self, key: Any, value: Any) -> None:
        now = self._timer()
        # Invariant 1: Expire before evict
        self.expire(now)

        exp = self._ttu(key, value, now)
        if exp <= now:
            if key in self._data:
                del self._data[key]
            return

        if key in self._data:
            self._data.move_to_end(key)

        # Invariant 3: LRU & Size
        if key not in self._data and len(self._data) >= self.maxsize:
            self.popitem()

        self._data[key] = (value, exp)

    def __delitem__(self, key: Any) -> None:
        if key not in self._data:
            raise KeyError(key)
        del self._data[key]

    def __contains__(self, key: Any) -> bool:
        self.expire()
        return key in self._data

    def __len__(self) -> int:
        self.expire()
        return len(self._data)

    @property
    def currsize(self) -> int:
        self.expire()
        return len(self._data)

    def popitem(self) -> Tuple[Any, Any]:
        # Pop the least recently used item
        key, (val, exp) = self._data.popitem(last=False)
        return key, val

